## 3. Result-Generation Logic (form data → recommendation)

The result logic is defined inline in the Compass page (there is no separate `lib/` file). The `InsomniaInputs` type, `defaultInputs`, and the `evaluate()` function follow.

Source: `client/src/pages/ChronicInsomniaCompass.tsx`

```typescript
interface InsomniaInputs {
  type: "sleep_onset" | "sleep_maintenance" | "both" | "early_awakening";
  duration_months: string;
  isi_score: string;
  frequency_nights_per_week: string;
  daytime_impairment: boolean;
  cbti_completed: boolean;
  cbti_response: "not_tried" | "partial" | "inadequate" | "contraindicated";
  comorbid_depression: boolean;
  comorbid_anxiety: boolean;
  comorbid_pain: boolean;
  comorbid_osa: boolean;
  comorbid_rls: boolean;
  comorbid_substance: boolean;
  prior_benzo: boolean;
  prior_zdrug: boolean;
  prior_orexin: boolean;
  prior_doxepin: boolean;
  pregnancy: boolean;
  age_over_65: boolean;
  hepatic_impairment: boolean;
}

const defaultInputs: InsomniaInputs = {
  type: "both",
  duration_months: "",
  isi_score: "",
  frequency_nights_per_week: "",
  daytime_impairment: true,
  cbti_completed: false,
  cbti_response: "not_tried",
  comorbid_depression: false,
  comorbid_anxiety: false,
  comorbid_pain: false,
  comorbid_osa: false,
  comorbid_rls: false,
  comorbid_substance: false,
  prior_benzo: false,
  prior_zdrug: false,
  prior_orexin: false,
  prior_doxepin: false,
  pregnancy: false,
  age_over_65: false,
  hepatic_impairment: false,
};

function evaluate(inputs: InsomniaInputs) {
  const durationMonths = parseFloat(inputs.duration_months);
  const isiScore = parseInt(inputs.isi_score);
  const freqNights = parseFloat(inputs.frequency_nights_per_week);

  const isChronicInsomnia = durationMonths >= 3 && freqNights >= 3 && inputs.daytime_impairment;
  const severity: "mild" | "moderate" | "severe" =
    isiScore >= 22 ? "severe" : isiScore >= 15 ? "moderate" : "mild";

  const firstLine: string[] = [];
  const secondLine: string[] = [];
  const avoidList: string[] = [];

  // AASM 2017 + April 2026 CPG
  firstLine.push("Cognitive Behavioral Therapy for Insomnia (CBT-I) — AASM: Strong recommendation (first-line for all chronic insomnia)");

  if (inputs.cbti_response === "partial" || inputs.cbti_response === "inadequate") {
    // Pharmacologic options per AASM 2017 CPG
    if (!inputs.age_over_65 && !inputs.hepatic_impairment) {
      firstLine.push("Suvorexant (Belsomra) 10–20 mg — AASM: Strong recommendation (sleep onset + maintenance)");
      firstLine.push("Lemborexant (Dayvigo) 5–10 mg — AASM: Strong recommendation (sleep onset + maintenance)");
    }
    if (inputs.type === "sleep_maintenance" || inputs.type === "both" || inputs.type === "early_awakening") {
      firstLine.push("Doxepin 3–6 mg — AASM: Strong recommendation (sleep maintenance only)");
    }
    if (!inputs.comorbid_substance) {
      secondLine.push("Eszopiclone (Lunesta) 1–3 mg — AASM: Conditional recommendation");
      secondLine.push("Zolpidem (Ambien) 5–10 mg — AASM: Conditional recommendation");
      secondLine.push("Triazolam 0.125–0.25 mg — AASM: Conditional recommendation (short-term only)");
    }
    if (inputs.comorbid_depression) {
      secondLine.push("Trazodone 50–150 mg — commonly used off-label; limited RCT evidence");
    }
  }

  if (inputs.cbti_response === "not_tried") {
    firstLine.push("⚠️ CBT-I should be attempted before pharmacotherapy per AASM 2017 and 2026 guidelines");
  }

  // AASM April 2026: combination CBT-I + medication
  if (inputs.cbti_response === "partial") {
    firstLine.push("AASM April 2026 CPG: Combination CBT-I + pharmacotherapy conditionally recommended for partial CBT-I responders");
  }

  if (inputs.age_over_65) {
    avoidList.push("Benzodiazepines (fall risk, cognitive impairment — AASM: Against)");
    avoidList.push("Z-drugs at standard doses (reduce dose by 50% — AASM: Conditional)");
    avoidList.push("Diphenhydramine (Benadryl) — AASM: Against; anticholinergic risk");
  }
  if (inputs.comorbid_substance) {
    avoidList.push("Benzodiazepines and Z-drugs (abuse potential)");
  }
  if (inputs.pregnancy) {
    avoidList.push("All pharmacologic agents — safety data insufficient; CBT-I is first-line");
  }

  avoidList.push("OTC antihistamines (diphenhydramine, doxylamine) — AASM: Against for chronic insomnia");
  avoidList.push("Melatonin — AASM: Weak evidence for chronic insomnia; not recommended as primary treatment");
  avoidList.push("Tryptophan, valerian — AASM: Insufficient evidence");

  const authRequired = inputs.cbti_response !== "not_tried";
  const appealStrength: "strong" | "moderate" | "weak" =
    isChronicInsomnia && inputs.cbti_response !== "not_tried" ? "strong" : "moderate";

  const keyFindings: string[] = [];
  if (isChronicInsomnia) keyFindings.push(`Chronic insomnia disorder: ≥${durationMonths} months, ≥${freqNights} nights/week, with daytime impairment (ICSD-3 criteria met)`);
  if (isiScore) keyFindings.push(`ISI score: ${isiScore}/28 — ${severity} insomnia`);
  if (inputs.cbti_response !== "not_tried") keyFindings.push(`CBT-I trial: ${inputs.cbti_response === "partial" ? "Partial response" : "Inadequate response"} — pharmacotherapy indicated`);
  if (inputs.comorbid_depression) keyFindings.push("Comorbid depression — consider dual-action agent (trazodone, mirtazapine)");
  if (inputs.comorbid_osa) keyFindings.push("Comorbid OSA — ensure PAP therapy optimized before treating residual insomnia");

  return { isChronicInsomnia, severity, firstLine, secondLine, avoidList, authRequired, appealStrength, keyFindings };
}
